package cn.studypilot.assessment.controller;
import cn.studypilot.assessment.dto.SubmitAttemptRequest; import cn.studypilot.assessment.model.*; import cn.studypilot.assessment.service.AssessmentService; import cn.studypilot.common.config.RequestIdFilter; import cn.studypilot.common.response.ApiResponse; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/assessments") @ConditionalOnProperty(prefix="studypilot.database",name="url")
public class AssessmentController {private final AssessmentService service;public AssessmentController(AssessmentService service){this.service=service;}@PostMapping("/attempts") public ApiResponse<java.util.Map<String,Long>> start(@RequestParam long projectId,@RequestParam long examId,HttpServletRequest r){return new ApiResponse<>(java.util.Map.of("attemptId",service.start(projectId,examId)),r.getAttribute(RequestIdFilter.ATTRIBUTE).toString());}@PostMapping("/attempts/{attemptId}/submit") public ApiResponse<AssessmentReport> submit(@PathVariable long attemptId,@RequestParam long projectId,@Valid @RequestBody SubmitAttemptRequest body,HttpServletRequest r){var answers=body.answers().stream().map(a->new SubmittedAnswer(a.itemId(),a.answer())).toList();return new ApiResponse<>(service.submit(projectId,attemptId,answers),r.getAttribute(RequestIdFilter.ATTRIBUTE).toString());}}
